    /// Redaction must strip the cross-repo (repo:client) org item and affected
    /// symbol when the caller may only see repo:api, while `None` (the
    /// backward-compatible default) leaves the full result intact.
    #[test]
    fn tool_blast_radius_redacts_to_visible_repos() {
        let store = cross_repo_store();
        let args = json!({ "changed_files": ["src/api.rs"] });

        // None ⇒ no scoping ⇒ the cross-repo consumer is present.
        let full = tool_blast_radius(&store, args.clone(), None, None).unwrap();
        let full_str = serde_json::to_string(&full).unwrap();
        assert!(
            full_str.contains("repo:client"),
            "unredacted result must name the downstream repo; got: {full_str}"
        );
        assert!(
            full_str.contains("Caller"),
            "unredacted result must include the cross-repo affected symbol"
        );
        assert!(
            !full["org_wide"].is_null(),
            "unredacted result must carry org_wide impact"
        );

        // Only(repo:api) ⇒ everything naming repo:client is redacted out.
        let visible = VisibleRepos::Only(["repo:api".to_string()].into_iter().collect());
        let scoped = tool_blast_radius(&store, args, None, Some(&visible)).unwrap();
        let scoped_str = serde_json::to_string(&scoped).unwrap();
        assert!(
            !scoped_str.contains("repo:client"),
            "redacted result must not leak the hidden repo; got: {scoped_str}"
        );
        assert!(
            !scoped_str.contains("Caller"),
            "redacted result must drop the hidden repo's affected symbol"
        );
        assert!(
            scoped["org_wide"].is_null(),
            "org_wide collapses to null once its only item (repo:client) is hidden"
        );
    }

    /// A two-repo store where one repo (`repo:kory-brain:10daef553576`) has a
    /// display `name` (`bx-react-native-client`) and the other does not — the
    /// measured nw-428 shape, where 29 of 44 real repos have `name: null`.
    /// `root` is called by `dependent`, both in the named repo, so a `repo`
    /// filter that resolves correctly finds a non-zero affected set; one that
    /// silently fails to resolve (the pre-fix bug: raw string compared only
    /// against known repo UIDS) reports zero with `repos_not_indexed`
    /// naming the filter value.
    fn named_repo_store() -> GraphStore {
        let store = GraphStore::in_memory().expect("in_memory store");
        let named = Repo {
            uid: "repo:kory-brain:10daef553576".to_string(),
            url: "https://example.test/bx-react-native-client".to_string(),
            indexed_sha: String::new(),
            staleness_commits_behind: 0,
            instance_id: "inst".to_string(),
            name: Some("bx-react-native-client".to_string()),
            root_path: None,
        };
        let unnamed = Repo {
            uid: "repo:kory-brain:deadbeefcafe".to_string(),
            url: "https://example.test/unnamed".to_string(),
            indexed_sha: String::new(),
            staleness_commits_behind: 0,
            instance_id: "inst".to_string(),
            name: None,
            root_path: None,
        };
        let symbol = |uid: &str, name: &str, repo_uid: &str, file: &str| Symbol {
            uid: uid.to_string(),
            name: name.to_string(),
            kind: SymbolKind::Function,
            repo_uid: repo_uid.to_string(),
            file_path: file.to_string(),
            start_line: 1,
            end_line: 2,
            signature: format!("fn {name}()"),
            summary: None,
            content_hash: format!("h_{uid}"),
            embedding: None,
            pagerank_score: None,
            is_entry_point: false,
            entry_point_kind: None,
            visibility: Visibility::Inferred,
            type_info: None,
            framework_hint: None,
            canonical_id: None,
        };

        store.insert_repo(&named).unwrap();
        store.insert_repo(&unnamed).unwrap();
        store
            .insert_symbol(&symbol(
                "root",
                "Root",
                &named.uid,
                "src/theme/ThemeContext.tsx",
            ))
            .unwrap();
        store
            .insert_symbol(&symbol(
                "dependent",
                "Dependent",
                &named.uid,
                "src/consumer.tsx",
            ))
            .unwrap();
        store
            .insert_edge(&ResolvedEdge {
                source_uid: "dependent".to_string(),
                target_uid: "root".to_string(),
                edge_type: EdgeType::Calls,
                confidence: 0.9,
                link_type: None,
                evidence: vec![],
            })
            .unwrap();
        store
    }

    /// nw-428. `--repo`/`repo` accepts the exact repo_uid, the exact display
    /// `name` `list_repos` prints, and (per `resolve_repo_selector`'s
    /// precedence) an exact URL/root-path match — the SAME resolver `impact
    /// --repo` already uses, reused rather than re-implemented.
    ///
    /// COUNTERWEIGHT: reverting `tool_blast_radius`'s `repo` resolution to the
    /// pre-fix `args.get("repo").and_then(|v| v.as_str()).map(str::to_string)`
    /// (raw passthrough, no `resolve_repo_filter` call) makes this test FAIL —
    /// the by-name run then reports `affected_symbol_count: 0` and
    /// `repos_not_indexed: ["bx-react-native-client"]` while by-uid still
    /// reports 1, so the first assertion (`by_uid == by_name`) trips. Verified
    /// by hand before committing this test.
    #[test]
    fn tool_blast_radius_repo_filter_resolves_by_name_and_by_uid_identically() {
        let store = named_repo_store();

        let by_uid = tool_blast_radius(
            &store,
            json!({ "changed_files": ["src/theme/ThemeContext.tsx"], "repo": "repo:kory-brain:10daef553576" }),
            None,
            None,
        )
        .unwrap();
        let by_name = tool_blast_radius(
            &store,
            json!({ "changed_files": ["src/theme/ThemeContext.tsx"], "repo": "bx-react-native-client" }),
            None,
            None,
        )
        .unwrap();

        assert_eq!(
            by_uid["affected_symbol_count"], by_name["affected_symbol_count"],
            "by-uid ({by_uid}) and by-name ({by_name}) must agree on affected_symbol_count"
        );
        assert!(
            by_uid["affected_symbol_count"].as_u64().unwrap() > 0,
            "the fixture's dependent edge must actually surface an affected symbol; got {by_uid}"
        );
        assert_eq!(by_uid["status"], "complete");
        assert_eq!(by_name["status"], "complete");
        assert_eq!(by_uid["gate_state"], by_name["gate_state"]);
        assert_eq!(
            by_name["coverage"]["repos_not_indexed"],
            json!([]),
            "resolving `repo` by its printed NAME must not report it as not-indexed; got {by_name}"
        );
    }

    /// nw-428's companion half: a `repo` value that resolves to nothing must
    /// REFUSE (the tool call errors) rather than silently answering a
    /// confident `affected_symbol_count: 0` / `gate_state: degraded-unknown`
    /// that reads as "nothing depends on this file, safe to change" — AND
    /// the refusal must name a remedy (nw-334's standard), not just fail.
    ///
    /// COUNTERWEIGHT: the pre-fix passthrough behavior returns `Ok(_)` here
    /// with `affected_symbol_count: 0`, so asserting `.is_err()` fails against
    /// the un-fixed code — confirmed by hand before committing. Asserting on
    /// the message text (not just `.is_err()`) is itself a fix: the original
    /// version of this test only checked `is_err()`, which would have passed
    /// against a refusal that named no remedy at all.
    #[test]
    fn tool_blast_radius_unresolvable_repo_filter_refuses_rather_than_answering_zero() {
        let store = named_repo_store();
        let result = tool_blast_radius(
            &store,
            json!({
                "changed_files": ["src/theme/ThemeContext.tsx"],
                "repo": "this-repo-does-not-exist",
            }),
            None,
            None,
        );
        let error = format!(
            "{:#}",
            result.expect_err(
                "an unresolvable `repo` filter must refuse the analysis, not answer 0 affected"
            )
        );
        assert!(
            error.contains("this-repo-does-not-exist"),
            "the refusal must name the selector that failed; got {error:?}"
        );
        assert!(
            error.contains("list-repos"),
            "the refusal must name a remedy the caller can execute (nw-334); got {error:?}"
        );
        assert!(
            error.contains("bx-react-native-client") && error.contains("unnamed"),
            "the refusal should help a caller pick the right key by naming what IS indexed; \
             got {error:?}"
        );
    }

    #[test]
    fn restricted_symbol_topology_tools_never_cross_a_two_repo_boundary() {
        let store = cross_repo_store();
        let api_only = VisibleRepos::Only(["repo:api".to_string()].into_iter().collect());
        let client_only = VisibleRepos::Only(["repo:client".to_string()].into_iter().collect());

        let contracts =
            tool_cross_repo_contracts(&store, json!({ "uid": "api" }), Some(&api_only)).unwrap();
        let contracts_json = serde_json::to_string(&contracts).unwrap();
        assert!(!contracts_json.contains("repo:client"), "{contracts_json}");
        assert!(!contracts_json.contains("Caller"), "{contracts_json}");

        let flow = tool_flow_trace(
            &store,
            json!({ "symbol": "Caller", "max_depth": 3 }),
            None,
            Some(&client_only),
        )
        .unwrap();
        let flow_json = serde_json::to_string(&flow).unwrap();
        assert!(!flow_json.contains("repo:api"), "{flow_json}");
        assert!(!flow_json.contains("Handler"), "{flow_json}");
        assert!(
            tool_flow_trace(
                &store,
                json!({ "symbol": "Handler" }),
                None,
                Some(&client_only),
            )
            .is_err(),
            "a hidden seed must look absent"
        );
    }

    #[test]
    fn detect_changes_recomputes_visible_counts_and_suppresses_unowned_process_details() {
        let store = cross_repo_store();
        let mut hidden = store.lookup_symbol("client").unwrap();
        hidden.uid = "hidden-same-path".to_string();
        hidden.name = "HiddenSamePath".to_string();
        hidden.file_path = "src/api.rs".to_string();
        store.insert_symbol(&hidden).unwrap();

        let visible = VisibleRepos::Only(["repo:api".to_string()].into_iter().collect());
        let result = tool_detect_changes_scoped(
            &store,
            json!({ "changed_files": ["src/api.rs"] }),
            Some(&visible),
        )
        .unwrap();
        let encoded = serde_json::to_string(&result).unwrap();
        assert!(!encoded.contains("HiddenSamePath"), "{encoded}");
        assert!(!encoded.contains("repo:client"), "{encoded}");
        assert_eq!(result["affected_symbol_count"], 1);
        assert_eq!(result["affected_process_count"], 0);
        assert_eq!(result["gate_state"], "degraded-unknown");
        assert_eq!(result["risk"], Value::Null);
        assert_eq!(result["process_analysis_unavailable"], true);
    }

    #[test]
    fn restricted_edge_tools_redact_hidden_resolver_staleness_and_fail_closed() {
        let dir = tempfile::tempdir().unwrap();
        let store = GraphStore::open_or_create(&dir.path().join("resolver-scope.lbug")).unwrap();
        let repo = |uid: &str| Repo {
            uid: uid.to_string(),
            url: format!("https://example.test/{uid}"),
            indexed_sha: String::new(),
            staleness_commits_behind: 0,
            instance_id: "inst".to_string(),
            name: None,
            root_path: None,
        };
        for uid in ["repo:visible", "repo:hidden"] {
            store.insert_repo(&repo(uid)).unwrap();
        }
        let symbol = |uid: &str, name: &str, repo_uid: &str| Symbol {
            uid: uid.to_string(),
            name: name.to_string(),
            kind: SymbolKind::Function,
            repo_uid: repo_uid.to_string(),
            file_path: "src/shared.rs".to_string(),
            start_line: 1,
            end_line: 2,
            signature: format!("fn {name}()"),
            summary: None,
            content_hash: format!("hash:{uid}"),
            embedding: None,
            pagerank_score: None,
            is_entry_point: false,
            entry_point_kind: None,
            visibility: Visibility::Public,
            type_info: None,
            framework_hint: None,
            canonical_id: None,
        };
        store
            .insert_symbol(&symbol("visible-symbol", "VisibleSymbol", "repo:visible"))
            .unwrap();
        store
            .insert_symbol(&symbol("hidden-symbol", "HiddenSymbol", "repo:hidden"))
            .unwrap();

        // No resolver-generation sidecar: both repositories are incompatible,
        // but the restricted caller must see only its own stale UID.
        let visible = VisibleRepos::Only(["repo:visible".to_string()].into_iter().collect());
        let detect = tool_detect_changes_scoped(
            &store,
            json!({ "changed_files": ["src/shared.rs"] }),
            Some(&visible),
        )
        .unwrap();
        let detect_json = serde_json::to_string(&detect).unwrap();
        assert!(detect_json.contains("repo:visible"), "{detect_json}");
        assert!(!detect_json.contains("repo:hidden"), "{detect_json}");
        assert!(!detect_json.contains("HiddenSymbol"), "{detect_json}");

        let impact = tool_brain_impact(
            &store,
            json!({ "symbol": "VisibleSymbol" }),
            None,
            Some(&visible),
        )
        .unwrap_err()
        .to_string();
        assert!(impact.contains("brain_impact refused"), "{impact}");
        assert!(impact.contains("repo:visible"), "{impact}");
        assert!(!impact.contains("repo:hidden"), "{impact}");
        assert!(impact.contains("--force"), "{impact}");
    }

    /// The shared `resolver-generation-incompatible` descriptor is what a CI
    /// consumer keys on -- the prose message is redacted for a restricted
    /// caller, so the descriptor is the only machine-readable signal left. The
    /// restricted `detect_changes` path returns early with its own hand-built
    /// payload and carried only the authz notification, so the same stale graph
    /// announced itself on the unrestricted route and stayed silent on the
    /// restricted one.
    #[test]
    fn restricted_detect_changes_still_carries_the_resolver_incompatibility_descriptor() {
        let dir = tempfile::tempdir().unwrap();
        let store = GraphStore::open_or_create(&dir.path().join("descriptor.lbug")).unwrap();
        store
            .insert_repo(&Repo {
                uid: "repo:visible".to_string(),
                url: "https://example.test/visible".to_string(),
                indexed_sha: String::new(),
                staleness_commits_behind: 0,
                instance_id: "inst".to_string(),
                name: None,
                root_path: None,
            })
            .unwrap();

        let descriptor = nestweaver_engine::resolver_generation::INCOMPATIBLE_RESOLVER_DESCRIPTOR;
        let has_descriptor = |value: &Value| {
            value["notifications"]
                .as_array()
                .is_some_and(|notifications| {
                    notifications.iter().any(|n| n["descriptor"] == descriptor)
                })
        };

        // No sidecar, so the repository is resolver-incompatible on both routes.
        let unrestricted =
            tool_detect_changes_scoped(&store, json!({ "changed_files": ["src/a.rs"] }), None)
                .unwrap();
        assert!(
            has_descriptor(&unrestricted),
            "precondition: the unrestricted route announces incompatibility: {unrestricted}"
        );

        let visible = VisibleRepos::Only(["repo:visible".to_string()].into_iter().collect());
        let restricted = tool_detect_changes_scoped(
            &store,
            json!({ "changed_files": ["src/a.rs"] }),
            Some(&visible),
        )
        .unwrap();
        assert_eq!(
            restricted["resolver_stale_repos"],
            json!(["repo:visible"]),
            "{restricted}"
        );
        assert!(
            has_descriptor(&restricted),
            "the restricted route must carry the same descriptor: {restricted}"
        );
    }

    #[test]
    fn two_tier_local_tools_redact_hidden_repo_symbols_and_counts() {
        let store = mixed_visibility_store();
        let visible = VisibleRepos::Only(
            ["repo:api".to_string(), "repo:a".to_string()]
                .into_iter()
                .collect(),
        );
        let mut hidden_target = store
            .lookup_symbols_by_name("HiddenCaller")
            .expect("hidden template")
            .remove(0);
        hidden_target.uid = "hidden-target".to_string();
        hidden_target.name = "Target".to_string();
        hidden_target.file_path = "hidden/target.rs".to_string();
        store
            .insert_symbol(&hidden_target)
            .expect("hidden same-name target");
        let mut visible_via_hidden = hidden_target.clone();
        visible_via_hidden.uid = "visible-via-hidden".to_string();
        visible_via_hidden.name = "VisibleViaHidden".to_string();
        visible_via_hidden.repo_uid = "repo:a".to_string();
        visible_via_hidden.file_path = "src/visible_via_hidden.rs".to_string();
        store
            .insert_symbol(&visible_via_hidden)
            .expect("visible transitive caller");
        store
            .insert_edge(&ResolvedEdge {
                source_uid: visible_via_hidden.uid.clone(),
                target_uid: "hidden".to_string(),
                edge_type: EdgeType::Calls,
                confidence: 0.9,
                link_type: None,
                evidence: vec![],
            })
            .expect("hidden-intermediate edge");

        let impact = tool_brain_impact(&store, json!({ "symbol": "Target" }), None, Some(&visible))
            .expect("scoped impact");
        let impact_text = impact.to_string();
        assert_eq!(
            impact["status"], "ok",
            "a hidden same-name symbol must not make the visible target ambiguous"
        );
        assert!(impact_text.contains("VisibleCaller"), "{impact}");
        assert!(!impact_text.contains("HiddenCaller"), "{impact}");
        assert!(!impact_text.contains("LocalCaller"), "{impact}");
        assert!(!impact_text.contains("VisibleViaHidden"), "{impact}");
        assert!(!impact_text.contains("hidden/target.rs"), "{impact}");
        assert_eq!(impact["total"], 1);
        assert_eq!(impact["returned"], 1);

        let mut visible_test = store
            .lookup_symbols_by_name("VisibleCaller")
            .expect("visible template")
            .remove(0);
        visible_test.uid = "visible-test".to_string();
        visible_test.name = "visible_target_test".to_string();
        visible_test.file_path = "tests/visible_target_test.rs".to_string();
        store.insert_symbol(&visible_test).expect("visible test");
        let mut hidden_test = visible_test.clone();
        hidden_test.uid = "hidden-test".to_string();
        hidden_test.name = "hidden_target_test".to_string();
        hidden_test.repo_uid = "repo:b".to_string();
        hidden_test.file_path = "hidden/tests/hidden_target_test.rs".to_string();
        store.insert_symbol(&hidden_test).expect("hidden test");
        let mut hidden_same_path_test = hidden_test.clone();
        hidden_same_path_test.uid = "hidden-same-path-test".to_string();
        hidden_same_path_test.name = "hidden_same_path_test".to_string();
        hidden_same_path_test.file_path = visible_test.file_path.clone();
        store
            .insert_symbol(&hidden_same_path_test)
            .expect("hidden same-path test");
        for source_uid in ["visible-test", "hidden-test"] {
            store
                .insert_edge(&ResolvedEdge {
                    source_uid: source_uid.to_string(),
                    target_uid: "target".to_string(),
                    edge_type: EdgeType::Calls,
                    confidence: 0.9,
                    link_type: None,
                    evidence: vec![],
                })
                .expect("test edge");
        }
        store
            .insert_edge(&ResolvedEdge {
                source_uid: hidden_same_path_test.uid,
                target_uid: "target".to_string(),
                edge_type: EdgeType::Calls,
                confidence: 0.7,
                link_type: None,
                evidence: vec![],
            })
            .expect("hidden same-path test edge");

        let tests = tool_affected_tests(
            &store,
            json!({ "changed_files": ["src/target.rs"] }),
            Some(&visible),
        )
        .expect("scoped affected tests");
        let tests_text = tests.to_string();
        assert!(tests_text.contains("visible_target_test"), "{tests}");
        assert!(!tests_text.contains("hidden_target_test"), "{tests}");
        assert!(!tests_text.contains("hidden_same_path_test"), "{tests}");
        assert!(!tests_text.contains("hidden/tests"), "{tests}");
        assert_eq!(
            tests["summary"],
            "1 tier-1, 0 tier-2, 0 tier-3 tests affected"
        );
    }

    #[test]
    fn blast_radius_count_is_independent_of_limit() {
        let store = GraphStore::in_memory().expect("in_memory store");
        let mk = |uid: &str, name: &str, file: &str| Symbol {
            uid: uid.to_string(),
            name: name.to_string(),
            kind: SymbolKind::Function,
            repo_uid: "repo:api".to_string(),
            file_path: file.to_string(),
            start_line: 1,
            end_line: 1,
            signature: format!("fn {name}()"),
            summary: None,
            content_hash: format!("h_{uid}"),
            embedding: None,
            pagerank_score: None,
            is_entry_point: false,
            entry_point_kind: None,
            visibility: Visibility::Inferred,
            type_info: None,
            framework_hint: None,
            canonical_id: None,
        };

        store
            .insert_symbol(&mk("target", "fn_target", "src/target.rs"))
            .unwrap();
        for i in 0..60 {
            let uid = format!("caller:{i}");
            store
                .insert_symbol(&mk(
                    &uid,
                    &format!("fn_caller_{i}"),
                    &format!("src/caller_{i}.rs"),
                ))
                .unwrap();
            store
                .insert_edge(&ResolvedEdge {
                    source_uid: uid,
                    target_uid: "target".to_string(),
                    edge_type: EdgeType::Calls,
                    confidence: 0.9,
                    link_type: None,
                    evidence: vec![],
                })
                .unwrap();
        }

        let result = tool_blast_radius(
            &store,
            json!({ "changed_files": ["src/target.rs"], "limit": 5 }),
            None,
            None,
        )
        .unwrap();

        assert_eq!(result["affected_symbol_count"], json!(60));
        assert_eq!(result["returned_affected_symbol_count"], json!(5));
        assert_eq!(result["affected_symbols_truncated"], json!(true));
        assert_eq!(result["affected_symbols"].as_array().unwrap().len(), 5);
    }

    #[test]
    fn blast_radius_authz_precedes_limit_and_sarif_count_exposure() {
        let store = mixed_visibility_store();
        let visible = VisibleRepos::Only(["repo:a".to_string()].into_iter().collect());
        let args = json!({ "changed_files": ["src/target.rs"], "limit": 1 });

        let result = tool_blast_radius(&store, args.clone(), None, Some(&visible)).unwrap();
        assert_eq!(result["affected_symbol_count"], json!(2));
        assert_eq!(result["returned_affected_symbol_count"], json!(1));
        assert_eq!(result["affected_symbols_truncated"], json!(true));
        assert_eq!(result["affected_symbols"].as_array().unwrap().len(), 1);
        assert!(
            result["summary"]
                .as_str()
                .unwrap()
                .contains("2 transitively affected")
        );
        let serialized = serde_json::to_string(&result).unwrap();
        assert!(!serialized.contains("repo:b"));
        assert!(!serialized.contains("HiddenCaller"));
        assert!(!serialized.contains("src/hidden.rs"));
        assert!(!serialized.contains("repo:api"));
        assert!(!serialized.contains("Target"));
        assert!(result["org_wide"].is_null());

        let sarif = tool_blast_radius(
            &store,
            json!({
                "changed_files": ["src/target.rs"],
                "limit": 1,
                "format": "sarif"
            }),
            None,
            Some(&visible),
        )
        .unwrap();
        let props = &sarif["runs"][0]["properties"];
        assert_eq!(props["nestweaver/affectedSymbolCount"], json!(2));
        assert_eq!(props["nestweaver/returnedAffectedSymbolCount"], json!(1));
        assert_eq!(props["nestweaver/affectedSymbolsTruncated"], json!(true));
        let serialized = serde_json::to_string(&sarif).unwrap();
        assert!(!serialized.contains("repo:b"));
        assert!(!serialized.contains("HiddenCaller"));
        assert!(!serialized.contains("src/hidden.rs"));
        assert!(!serialized.contains("repo:api"));
        assert!(!serialized.contains("Target"));
        assert!(
            sarif["runs"][0]["results"]
                .as_array()
                .unwrap()
                .iter()
                .all(|result| result["ruleId"] != "nw/org-impact")
        );
    }

